update "ai_friend"
set header_image_addr=#{addr},character_history=#{history},is_complete=true
where ai_friend_id=#{aiFriendId}
and user_id=#{userId}
and is_delete=false and is_complete=false

update "ai_friend"
set is_delete=true
where ai_friend_id=#{aiFriendId}
and user_id=#{userId}
and is_delete=false
